<?= $this->extend('layouts/tenant_admin') ?><?= $this->section('content') ?>
<h1>Admission list publication</h1><?php if (session('message')): ?><p class="notice"><?= esc(session('message')) ?></p><?php endif ?><?php if (session('errors')): ?><ul><?php foreach(session('errors') as $error): ?><li><?= esc($error) ?></li><?php endforeach ?></ul><?php endif ?>
<section class="admin-grid"><?php foreach($metrics as $label => $count): ?><article class="admin-card"><strong><?= esc((string) $count) ?></strong><br><?= esc($label) ?> lists</article><?php endforeach ?></section>
<h2>Create publication draft</h2><form method="post" action="<?= site_url('tenant/admissions/lists') ?>"><?= csrf_field() ?><label>Cycle ID <input name="admission_cycle_id" inputmode="numeric" required></label><label>Programme opening ID <input name="programme_opening_id" inputmode="numeric"></label><label>Title <input name="title" required></label><label>Version <input name="version_number" inputmode="numeric" placeholder="Auto"></label><label>Export hook <select name="export_hook"><option value="csv">CSV</option><option value="pdf">PDF</option></select></label><label>Private notes <textarea name="private_notes"></textarea></label><button>Create draft</button></form>
<h2>Drafts and publications</h2><table><thead><tr><th>Title</th><th>Version</th><th>Status</th><th>Published</th><th></th></tr></thead><tbody><?php foreach($publications as $publication): ?><tr><td><?= esc($publication['title']) ?></td><td><?= esc((string) $publication['version_number']) ?></td><td><?= esc($publication['status']) ?></td><td><?= esc($publication['published_at'] ?? '') ?></td><td><a href="<?= site_url('tenant/admissions/lists/'.$publication['id']) ?>">Preview</a><?php if($publication['status']==='published'): ?> · <a href="<?= public_site_url('admission_list', [$publication['public_token']]) ?>">Public page</a><?php endif ?></td></tr><?php endforeach ?></tbody></table>
<?= $this->endSection() ?>
